func (this *BinanceCore) HandlePositions(client any, message any) {
	//
	//     {
	//         e: 'ACCOUNT_UPDATE',
	//         T: 1667881353112,
	//         E: 1667881353115,
	//         a: {
	//             B: [{
	//                 a: 'USDT',
	//                 wb: '1127.95750089',
	//                 cw: '1040.82091149',
	//                 bc: '0'
	//             }],
	//             P: [{
	//                 s: 'BTCUSDT',
	//                 pa: '-0.089',
	//                 ep: '19700.03933',
	//                 cr: '-1260.24809979',
	//                 up: '1.53058860',
	//                 mt: 'isolated',
	//                 iw: '87.13658940',
	//                 ps: 'BOTH',
	//                 ma: 'USDT'
	//             }],
	//             m: 'ORDER'
	//         }
	//     }
	//
	// each account is connected to a different endpoint
	// and has exactly one subscriptionhash which is the account type
	var subscriptions any = client.(ccxt.ClientInterface).GetSubscriptions()
	var subscriptionsKeys []string = ccxt.ObjectKeys(subscriptions)
	var accountType any = this.GetAccountTypeFromSubscriptions(subscriptionsKeys)
	if ccxt.IsEqual(this.Positions, nil) {
		this.Positions = map[string]any{}
	}
	if !(ccxt.InOp(this.Positions, accountType)) {
		ccxt.AddElementToObject(this.Positions, accountType, ccxt.NewArrayCacheBySymbolBySide())
	}
	var cache any = ccxt.GetValue(this.Positions, accountType)
	var data any = this.SafeDict(message, "a", map[string]any{})
	var rawPositions any = this.SafeList(data, "P", []any{})
	var newPositions any = []any{}
	for i := 0; ccxt.IsLessThan(i, ccxt.GetArrayLength(rawPositions)); i++ {
		var rawPosition any = ccxt.GetValue(rawPositions, i)
		var position any = this.ParseWsPosition(rawPosition)
		var timestamp *int64 = this.SafeInteger(message, "E")
		ccxt.AddElementToObject(position, "timestamp", timestamp)
		ccxt.AddElementToObject(position, "datetime", this.Iso8601(timestamp))
		ccxt.AppendToArray(&newPositions, position)
		cache.(ccxt.Appender).Append(position)
	}
	var messageHashes any = this.FindMessageHashes(ccxt.AsClient(client), ccxt.Add(accountType, ":positions::"))
	for i := 0; ccxt.IsLessThan(i, ccxt.GetArrayLength(messageHashes)); i++ {
		var messageHash any = ccxt.GetValue(messageHashes, i)
		var parts []string = ccxt.Split(messageHash, "::")
		var symbolsString any = ccxt.GetValue(parts, 1)
		var symbols []string = ccxt.Split(symbolsString, ",")
		var positions any = this.FilterByArray(newPositions, "symbol", symbols, false)
		if !ccxt.EvalTruthy(this.IsEmpty(positions)) {
			client.(ccxt.ClientInterface).Resolve(positions, messageHash)
		}
	}
	client.(ccxt.ClientInterface).Resolve(newPositions, ccxt.Add(accountType, ":positions"))
}
func (this *BinanceCore) ParseWsPosition(position any, optionalArgs ...any) any {
	//
	//     {
	//         "s": "BTCUSDT", // Symbol
	//         "pa": "0", // ccxt.Position Amount
	//         "ep": "0.00000", // Entry Price
	//         "cr": "200", // (Pre-fee) Accumulated Realized
	//         "up": "0", // Unrealized PnL
	//         "mt": "isolated", // Margin Type
	//         "iw": "0.00000000", // Isolated Wallet (if isolated position)
	//         "ps": "BOTH" // ccxt.Position Side
	//     }
	//
	market := ccxt.GetArg(optionalArgs, 0, nil)
	_ = market
	var marketId *string = this.SafeString(position, "s")
	var contracts *string = this.SafeString(position, "pa")
	var contractsAbs any = ccxt.Precise.StringAbs(this.SafeString(position, "pa"))
	var positionSide any = this.SafeStringLower(position, "ps")
	var hedged bool = true
	if ccxt.IsEqual(positionSide, "both") {
		hedged = false
		if !ccxt.Precise.StringEq(contracts, "0") {
			if ccxt.Precise.StringLt(contracts, "0") {
				positionSide = "short"
			} else {
				positionSide = "long"
			}
		}
	}
	return this.SafePosition(map[string]any{
		"info":                        position,
		"id":                          nil,
		"symbol":                      this.SafeSymbol(marketId, nil, nil, "swap"),
		"notional":                    nil,
		"marginMode":                  this.SafeString(position, "mt"),
		"liquidationPrice":            nil,
		"entryPrice":                  this.SafeNumber(position, "ep"),
		"unrealizedPnl":               this.SafeNumber(position, "up"),
		"percentage":                  nil,
		"contracts":                   this.ParseNumber(contractsAbs),
		"contractSize":                nil,
		"markPrice":                   nil,
		"side":                        positionSide,
		"hedged":                      hedged,
		"timestamp":                   nil,
		"datetime":                    nil,
		"maintenanceMargin":           nil,
		"maintenanceMarginPercentage": nil,
		"collateral":                  nil,
		"initialMargin":               nil,
		"initialMarginPercentage":     nil,
		"leverage":                    nil,
		"marginRatio":                 nil,
	})
}
func (this *BinanceCore) ParseWsOptionsPosition(position any, optionalArgs ...any) any {
	//
	//  from BALANCE_POSITION_UPDATE event P[] array:
	//  {
	//      "s": "BTC-251123-126000-C",  // option symbol
	//      "c": "-0.1000",              // position quantity (negative = short)
	//      "p": "-120.00000000",        // position value (USDT)
	//      "a": "1200.00000000"         // average entry price
	//  }
	//
	market := ccxt.GetArg(optionalArgs, 0, nil)
	_ = market
	var marketId *string = this.SafeString(position, "s")
	var contracts *string = this.SafeString(position, "c")
	var contractsAbs any = ccxt.Precise.StringAbs(contracts)
	var side any = nil
	if contracts != nil {
		if ccxt.Precise.StringLt(contracts, "0") {
			side = "short"
		} else if ccxt.Precise.StringGt(contracts, "0") {
			side = "long"
		}
	}
	return this.SafePosition(map[string]any{
		"info":                        position,
		"id":                          nil,
		"symbol":                      this.SafeSymbol(marketId, market, nil, "option"),
		"notional":                    this.SafeString(position, "p"),
		"marginMode":                  nil,
		"liquidationPrice":            nil,
		"entryPrice":                  this.SafeNumber(position, "a"),
		"unrealizedPnl":               nil,
		"percentage":                  nil,
		"contracts":                   this.ParseNumber(contractsAbs),
		"contractSize":                nil,
		"markPrice":                   nil,
		"side":                        side,
		"hedged":                      false,
		"timestamp":                   nil,
		"datetime":                    nil,
		"maintenanceMargin":           nil,
		"maintenanceMarginPercentage": nil,
		"collateral":                  nil,
		"initialMargin":               nil,
		"initialMarginPercentage":     nil,
		"leverage":                    nil,
		"marginRatio":                 nil,
	})
}

